import { CampusRenderer } from './renderer.js?v=20260927-doosan8c';
const $=s=>document.querySelector(s);
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,profiles,photos,research,viewer,selected,scope='all',photoIndex=0;
async function json(path){const response=await fetch(path);if(!response.ok)throw new Error(`${path}: ${response.status}`);return response.json()}
function displayNumber(b){return b.number?b.number.padStart(2,'0'):'—'}
function listBuildings(){
  const q=$('#search').value.trim().toLowerCase().replace(/동$/,'');
  const filtered=data.buildings.filter(b=>(scope==='all'||b.review)&&(!q||(/^\d+(?:-\d+)?$/.test(q)?b.number===q:`${b.number} ${b.name}`.toLowerCase().includes(q))));
  $('#result-count').textContent=`${filtered.length}개`;$('#list-title').textContent=scope==='review'?'외관 검토 대상':'건물 목록';
  $('#building-list').innerHTML=filtered.length?filtered.map(b=>`<button class="building-row${b.id===selected?' active':''}" data-id="${escapeHtml(b.id)}" aria-label="${escapeHtml(b.number?b.number+'동 ': '')}${escapeHtml(b.name)}" ${b.id===selected?'aria-current="true"':''}><span class="num">${escapeHtml(displayNumber(b))}</span><span class="row-name">${escapeHtml(b.name)}</span>${b.review?'<span class="dot" title="외관 추정 대상"></span>':b.geometryStatus==='schematic'?'<span class="dot schematic" title="위치만 확인 · 윤곽 미확인"></span>':''}</button>`).join(''):'<p class="empty">검색한 건물이 없습니다.</p>';
}
function renderInspector(){
  const b=data.buildings.find(b=>b.id===selected);if(!b){$('#inspector').hidden=true;return}
  const audit=research.buildings.find(item=>item.id===b.id);
  const record=photos.buildings.find(p=>String(p.number)===b.number&&b.review);const images=record?.images||[];photoIndex=Math.min(photoIndex,Math.max(0,images.length-1));const photo=images[photoIndex];const profile=profiles[b.number];const height=b.review&&$('#detail-toggle').checked?b.detailHeight:b.height;
  $('#inspector').hidden=false;
  $('#inspector').innerHTML=`<div class="inspector-heading"><span class="inspector-number">${escapeHtml(displayNumber(b))}</span><h2>${escapeHtml(b.name)}</h2><button class="icon-button" id="close-inspector" aria-label="건물 정보 닫기">×</button></div>${photo?`<div class="photo-frame"><img src="${escapeHtml(photo.path)}" alt="${escapeHtml(b.number+'동 '+b.name)} 실제 외관 참고 사진"><span class="photo-count">${photoIndex+1} / ${images.length}</span></div><div class="photo-nav"><a href="${escapeHtml(photo.sourcePage||record.sourcePage)}" target="_blank" rel="noreferrer">${escapeHtml(photo.sourceName||'서울대학교 공식 자료')} ↗</a>${images.length>1?'<div class="photo-buttons"><button id="prev-photo" aria-label="이전 사진">‹</button><button id="next-photo" aria-label="다음 사진">›</button></div>':''}</div>`:''}<p class="research-status"><strong>${audit?.modelStatus||'조사 대기'}</strong> · 검토 사진 ${audit?.reviewedPhotos||0} / ${audit?.minimum||research.minimum}장<br><small>여러 시점의 구조 대조와 정밀 검증이 필요합니다.</small></p><dl class="data-grid"><div><dt>지도 윤곽 면적</dt><dd>${b.area===null?'윤곽 미확인':'약 '+b.area.toLocaleString('ko-KR')+' m²'}</dd></div><div><dt>모형 높이</dt><dd>${height.toFixed(1)} m <span class="status">${b.heightBasis==='OSM 높이'&&!b.review?'지도 값':'추정'}</span></dd></div><div><dt>모형</dt><dd>${b.review&&$('#detail-toggle').checked?'사진 참고 초안':'사각형 기본 모형'}</dd></div></dl><p class="model-note">${escapeHtml(b.geometryStatus==='schematic'?'공식 지도에서 위치만 확인했습니다. 윤곽 자료가 없어 16 × 12m 임시 상자로 표시하며, 실제 면적·형태를 뜻하지 않습니다.':b.review?profile?.note||'외관을 추정한 모형입니다.':'건물 윤곽을 감싸는 사각형 모형입니다. '+b.heightBasis+'를 적용했습니다.')}${b.number==='7'&&b.review?'<br><strong>증축 공사 중 · 기존 외관 기준</strong>':''}</p>${profile?.structureFeatures?`<ul class="structure-features">${profile.structureFeatures.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul><div class="facade-actions"><button id="front-building" ${viewer.view==='2d'?'disabled':''}>정면 구조 보기</button><button id="side-building" ${viewer.view==='2d'?'disabled':''}>측면 구조 보기</button></div>`:''}<div class="model-actions"><button id="focus-building">가까이 보기</button><a href="${escapeHtml(record?.sourcePage||b.officialSource||b.source)}" target="_blank" rel="noreferrer">건물 자료 ↗</a></div>`;
  $('#close-inspector').onclick=()=>{selected=null;viewer.select(null);$('#inspector').hidden=true;listBuildings()};$('#focus-building').onclick=()=>viewer.focus(b,true);
  if($('#front-building'))$('#front-building').onclick=()=>{ $('#detail-toggle').checked=true;viewer.setDetail(true);viewer.facade(b);renderInspector() };
  if($('#side-building'))$('#side-building').onclick=()=>{ $('#detail-toggle').checked=true;viewer.setDetail(true);viewer.facade(b,true);renderInspector() };
  if($('#prev-photo'))$('#prev-photo').onclick=()=>{photoIndex=(photoIndex+images.length-1)%images.length;renderInspector()};
  if($('#next-photo'))$('#next-photo').onclick=()=>{photoIndex=(photoIndex+1)%images.length;renderInspector()};
}
function selectBuilding(id){selected=id;photoIndex=0;viewer.select(id);listBuildings();renderInspector();const b=data.buildings.find(b=>b.id===id);viewer.focus(b,true);$('#sidebar').classList.remove('open')}
function setScope(value){scope=value;document.querySelectorAll('[data-scope]').forEach(el=>{el.classList.toggle('active',el.dataset.scope===value);el.setAttribute('aria-pressed',el.dataset.scope===value)});$('#search').value='';listBuildings();viewer.reset(value);$('#map-location').textContent=value==='review'?'1–15동 외관 검토':'관악캠퍼스 전체';selected=null;viewer.select(null);$('#inspector').hidden=true;$('#sidebar').classList.remove('open')}
async function init(){
  [data,profiles,photos,research]=await Promise.all([json('./data/campus.json'),json('./data/profiles.json'),json('./data/photos.json?v=20260927-8'),json('./data/research-status.json?v=20260927-8')]);
  for(const rec of photos.buildings){const b=data.buildings.find(b=>b.review&&b.number===String(rec.number));if(b&&rec.officialName)b.name=rec.officialName;}
  viewer=new CampusRenderer($('#map'),$('#labels'),data,profiles,selectBuilding);
  $('#building-count').textContent=`${data.buildings.length}개 모형`;$('#coverage-note').textContent=`공식 건물 목록 ${data.coverage.officialEntries}개 항목을 모두 대조했습니다. 지도 윤곽 ${data.coverage.mappedFootprints}개와 윤곽이 없는 공식 위치 ${data.coverage.schematicEntries}개를 합쳐 ${data.coverage.totalModels}개 모형을 표시합니다. 주황색 임시 모형은 위치만 확인된 16 × 12m 상자이며 면적·형태는 미확인입니다. 최근 신축·철거·증축은 자료마다 시점이 다를 수 있습니다.`;
  listBuildings();$('#loading').hidden=true;
  $('#building-list').addEventListener('click',e=>{const row=e.target.closest('[data-id]');if(row)selectBuilding(row.dataset.id)});$('#search').addEventListener('input',listBuildings);
  document.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>setScope(el.dataset.scope));
  document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{const view=el.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===el);x.setAttribute('aria-pressed',x===el)});viewer.setView(view);viewer.select(selected);$('#map-help').textContent=view==='2d'?'드래그 이동 · 스크롤 확대':'드래그 회전 · 우클릭 이동 · 스크롤 확대';$('#detail-toggle').disabled=view==='2d';$('#map-description').textContent=view==='2d'?'지면 윤곽 · 북쪽 기준':'평면 지형 · 건물 높이 추정';renderInspector()});
  $('#detail-toggle').onchange=e=>{viewer.setDetail(e.target.checked);viewer.select(selected);renderInspector()};$('#zoom-in').onclick=()=>viewer.zoom(1.35);$('#zoom-out').onclick=()=>viewer.zoom(1/1.35);$('#north').onclick=()=>viewer.north();$('#reset-view').onclick=()=>setScope('all');
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');selected=null;viewer.select(null);$('#inspector').hidden=true;listBuildings()}});
}
$('#sources-button').onclick=()=>$('#sources-dialog').showModal();$('#close-sources').onclick=()=>$('#sources-dialog').close();$('#sources-dialog').addEventListener('click',e=>{if(e.target===$('#sources-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#open-list').onclick=()=>$('#sidebar').classList.add('open');$('#close-list').onclick=()=>$('#sidebar').classList.remove('open');
init().catch(error=>{console.error(error);$('#loading').hidden=true;$('#map-error').hidden=false;$('#map-error').innerHTML='<strong>지도를 불러오지 못했습니다.</strong><p>인터넷 연결과 브라우저의 WebGL 지원 여부를 확인한 뒤 새로고침해 주세요.</p><button onclick="location.reload()">다시 시도</button>';});
